*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f8fbff;font-synthesis:none} body{margin:0;background:#111b2d;overflow:hidden} button,input{font:inherit} button{color:inherit} #game-shell{position:relative;width:100vw;height:100dvh;min-height:520px;overflow:hidden;background:#92cbd3;isolation:isolate} #world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,21,37,.32),transparent 21%,transparent 68%,rgba(8,20,34,.22));z-index:1}.panel{background:rgba(15,27,45,.88);border:1px solid rgba(255,255,255,.12);box-shadow:0 12px 35px rgba(13,25,42,.22);backdrop-filter:blur(16px);border-radius:16px;z-index:3}.topbar{position:absolute;z-index:4;left:28px;right:28px;top:22px;height:54px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;filter:drop-shadow(0 2px 6px #18344466)}.brand strong{display:block;font:700 17px 'Space Grotesk';letter-spacing:1.9px;line-height:1}.brand small{font-size:9px;letter-spacing:2.65px;font-weight:700;color:#e3fbfb;opacity:.86}.brand-mark{width:37px;height:37px;display:flex;align-items:end;gap:3px;padding:7px;border-radius:11px;background:#ffca54;box-shadow:0 4px 10px #17354355;transform:rotate(-5deg)}.brand-mark span{display:block;background:#f27d47;border-radius:3px 3px 1px 1px;width:7px}.brand-mark span:first-child{height:13px}.brand-mark span:nth-child(2){height:19px;background:#f15f61}.brand-mark span:last-child{height:10px;background:#db4d79}.server-pill{position:absolute;left:50%;transform:translateX(-50%);border:1px solid #ffffff3d;background:#16364c65;border-radius:30px;padding:9px 14px;color:#effffe;font-size:10px;letter-spacing:1.25px;font-weight:800;backdrop-filter:blur(10px)}.server-pill i,.chat-dot,.location-tag i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#71efaa;margin-right:7px;box-shadow:0 0 9px #71efaa}.profile{display:flex;align-items:center;gap:9px;padding:5px 12px 5px 5px;border-radius:30px;background:#173449b8;border:1px solid #ffffff45;box-shadow:0 4px 14px #14364744;cursor:pointer;font-size:10px;font-weight:800;letter-spacing:.7px}.mini-avatar{height:31px;width:31px;border-radius:50%;background:#ffd082;color:#64462e;display:grid;place-items:center;font-size:19px}.chevron{font-size:16px;color:#b5d7dc}.quest-card{position:absolute;left:28px;top:104px;width:260px;padding:15px;display:flex;gap:12px;align-items:flex-start}.quest-icon{width:39px;height:39px;flex:none;border-radius:12px;background:linear-gradient(135deg,#ffc660,#ff8e69);display:grid;place-items:center;color:#fff4c4;font-size:20px;box-shadow:0 5px 13px #f4935655}.quest-copy{min-width:0;flex:1}.eyebrow{font-size:9px;letter-spacing:1.35px;font-weight:800;color:#a6bbc9}.eyebrow span{float:right;color:#ffd270}.quest-copy strong{font:700 15px 'Space Grotesk';display:block;margin-top:3px}.quest-copy p{font-size:11px;color:#b8c8d3;margin:3px 0 10px}.quest-progress{display:flex;align-items:center;gap:8px}.progress-track{height:5px;border-radius:9px;background:#34465a;flex:1;overflow:hidden}.progress-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,#ffbd54,#ffdd73);border-radius:9px;transition:width .25s}.quest-progress small{font-size:9px;color:#d9e3eb;font-weight:700}.coin-counter{position:absolute;top:105px;right:28px;padding:9px 14px;display:flex;gap:7px;align-items:center;border-radius:13px}.coin-glyph{color:#ffd263;font-size:19px;text-shadow:0 0 8px #f4a93f}.coin-counter strong{font:700 18px 'Space Grotesk'}.coin-counter small{font-size:9px;letter-spacing:1px;color:#aabdc8;font-weight:800;margin-left:2px}.chat{position:absolute;left:28px;bottom:94px;width:294px;height:260px;display:flex;flex-direction:column;overflow:hidden;transition:height .25s}.chat.collapsed{height:51px}.chat-heading{height:51px;flex:none;padding:10px 13px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff13}.chat-heading>div{display:grid;grid-template-columns:9px auto;grid-template-rows:14px 12px;column-gap:7px;align-items:center}.chat-dot{grid-row:1 / 3;margin:0;width:7px;height:7px}.chat-heading strong{font-size:10px;letter-spacing:1.2px}.chat-heading small{font-size:9px;color:#8da3b2}.chat-heading button{width:26px;height:26px;border:0;border-radius:8px;background:#ffffff0d;font-size:17px;color:#bbcad5;cursor:pointer}.chat-feed{padding:9px 13px;flex:1;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#50687c transparent;display:flex;flex-direction:column;gap:8px}.chat-line{font-size:11px;line-height:1.35;color:#d7e2e9;overflow-wrap:anywhere;animation:messageIn .2s ease-out}.chat-line .chat-name{font-weight:800;color:#84d7cd;margin-right:5px}.chat-line .chat-name.you{color:#ffc86b}.chat-line.system{color:#89a6b8;font-style:italic}.chat-form{display:flex;align-items:center;gap:7px;margin:0 10px 10px;padding:5px 6px 5px 10px;background:#0817268f;border:1px solid #ffffff16;border-radius:11px;flex:none}.chat-symbol{color:#86cfc6;font-size:13px}.chat-form input{flex:1;min-width:0;color:#f2f8fb;background:none;border:0;outline:none;font-size:10px}.chat-form input::placeholder{color:#768d9d}.chat-form button{border:0;border-radius:8px;background:#ffd06d;color:#293449;width:28px;height:27px;font-size:12px;cursor:pointer;transition:transform .15s,background .15s}.chat-form button:hover{transform:scale(1.05);background:#ffdf8d}.location-tag{position:absolute;right:28px;bottom:112px;padding:9px 12px;background:#1a3e4bb8;border:1px solid #ffffff4d;border-radius:9px;backdrop-filter:blur(8px);font-size:9px;font-weight:800;letter-spacing:1.2px;box-shadow:0 4px 14px #21434b44}.location-tag span{font-size:14px;margin-right:5px;color:#a8e8d0}.location-tag i{width:5px;height:5px;margin:0 0 1px 7px}.controls-hint{position:absolute;right:28px;bottom:66px;display:flex;align-items:center;gap:4px;color:#f2fcff;font-size:10px;font-weight:600;text-shadow:0 1px 4px #203943}.keycap{display:inline-grid;place-items:center;height:20px;min-width:20px;padding:0 5px;background:#1a3645b8;border:1px solid #ffffff50;border-radius:5px;font-size:9px;font-weight:800;box-shadow:0 2px #0e2631aa}.controls-hint>span:nth-child(4){margin-right:5px}.keycap.space{margin-left:7px;min-width:41px}.hotbar{position:absolute;z-index:4;bottom:19px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid #ffffff30;background:#193347c9;border-radius:16px;backdrop-filter:blur(12px);box-shadow:0 8px 24px #1028384a}.hotkey{position:relative;width:58px;height:56px;border:1px solid transparent;border-radius:11px;background:#ffffff0a;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:0;cursor:pointer;transition:all .15s}.hotkey:hover{background:#ffffff18;transform:translateY(-2px)}.hotkey.active{background:#ffc75a2d;border-color:#ffc75a99;box-shadow:inset 0 0 12px #ffc75a12}.hotkey-number{position:absolute;left:5px;top:3px;color:#91a5b4;font-size:8px;font-weight:700}.action-icon{font-size:21px;line-height:25px}.hotkey small{font-size:8px;letter-spacing:.8px;font-weight:800;color:#d1dee4}.hotbar-divider{height:34px;width:1px;background:#ffffff24;margin:0 2px}.settings-key{width:48px}.toast{position:absolute;z-index:8;top:83px;left:50%;transform:translate(-50%,-12px);opacity:0;padding:10px 16px;border:1px solid #ffffff30;background:#18384ddb;border-radius:10px;font-size:12px;font-weight:700;box-shadow:0 6px 18px #14304355;pointer-events:none;transition:all .25s}.toast.show{transform:translate(-50%,0);opacity:1}.mobile-controls{display:none;position:absolute;z-index:4;bottom:27px;left:22px;right:22px;justify-content:space-between;align-items:end;pointer-events:none}.joystick,.jump-button{pointer-events:auto;touch-action:none}.joystick{height:104px;width:104px;border-radius:50%;background:#18364855;border:1px solid #ffffff40;box-shadow:inset 0 0 15px #ffffff12;position:relative}.joy-knob{position:absolute;width:43px;height:43px;border-radius:50%;left:30px;top:30px;background:#d9f3efc4;border:1px solid #ffffff90;box-shadow:0 3px 12px #112c3888}.jump-button{width:69px;height:69px;border-radius:50%;border:1px solid #ffffff70;background:#ffce71d9;color:#303d4b;font-size:27px;font-weight:800;box-shadow:0 4px 16px #2c394955;display:flex;flex-direction:column;justify-content:center;align-items:center}.jump-button small{font-size:8px;letter-spacing:1px}.modal-backdrop{position:absolute;z-index:10;inset:0;background:#0713219c;backdrop-filter:blur(5px);display:grid;place-items:center;opacity:0;visibility:hidden;transition:opacity .2s}.modal-backdrop.open{opacity:1;visibility:visible}.modal{position:relative;width:min(410px,calc(100vw - 36px));padding:30px;color:#eef8fc;text-align:center;border-radius:22px;background:#182a40f2}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;color:#b9c9d4;font-size:23px;cursor:pointer}.modal-badge{margin:0 auto 12px;width:48px;height:48px;border-radius:15px;background:linear-gradient(135deg,#ffc95e,#ff8e71);display:grid;place-items:center;font-size:25px;color:#fff1b7}.modal h2{font:700 23px 'Space Grotesk';margin:0 0 8px}.modal>p{font-size:13px;line-height:1.5;color:#aebfcc;margin:0 auto 20px;max-width:320px}.help-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:left;margin-bottom:20px}.help-grid div{background:#ffffff08;border:1px solid #ffffff0f;border-radius:10px;padding:10px}.help-grid b{display:block;font-size:9px;letter-spacing:1px;color:#ffd16f;margin-bottom:4px}.help-grid span{font-size:10px;color:#bac8d2}.primary-button{width:100%;border:0;border-radius:11px;padding:12px;background:#ffca67;color:#243347;font-size:11px;font-weight:900;letter-spacing:1px;cursor:pointer}.primary-button span{float:right;font-size:16px;line-height:12px}.name-editor{position:absolute;z-index:7;right:28px;top:164px;width:208px;padding:13px;display:none}.name-editor.open{display:block}.name-editor>strong{font-size:9px;letter-spacing:1px;color:#aabdc9}.name-editor form{display:flex;gap:6px;margin-top:8px}.name-editor input{min-width:0;width:100%;background:#0b1c2b;border:1px solid #ffffff20;border-radius:7px;padding:8px;color:white;font-size:11px;outline:none}.name-editor button{border:0;border-radius:7px;background:#ffca67;color:#233348;font-size:10px;font-weight:900;padding:0 10px}@keyframes messageIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){#game-shell{min-height:480px}.topbar{left:15px;right:15px;top:13px}.brand strong{font-size:14px}.brand-mark{width:33px;height:33px}.server-pill{top:48px;font-size:8px;padding:7px 10px}.profile{padding-right:8px}.profile-name{display:none}.quest-card{left:14px;top:70px;width:208px;padding:10px;gap:8px}.quest-icon{width:32px;height:32px;font-size:17px}.quest-copy strong{font-size:13px}.quest-copy p{font-size:10px;margin-bottom:8px}.eyebrow{font-size:8px}.coin-counter{right:14px;top:74px;padding:8px 10px}.coin-counter small{display:none}.coin-counter strong{font-size:15px}.chat{left:12px;bottom:105px;width:min(258px,67vw);height:186px}.chat.collapsed{height:49px}.chat-feed{gap:6px;padding:7px 10px}.chat-line{font-size:10px}.chat-form{margin:0 7px 7px}.location-tag{right:12px;bottom:122px;font-size:8px;padding:7px 9px}.controls-hint{display:none}.hotbar{bottom:12px;gap:5px;padding:5px 7px}.hotkey{height:49px;width:49px}.settings-key{width:42px}.action-icon{font-size:19px}.mobile-controls{display:flex}.modal{padding:25px 20px}.name-editor{right:14px;top:122px}.vignette{background:linear-gradient(180deg,rgba(8,21,37,.3),transparent 19%,transparent 66%,rgba(8,20,34,.2))}}
@media(max-height:620px) and (min-width:701px){.chat{height:215px;bottom:84px}.hotbar{bottom:10px}.location-tag{bottom:98px}.controls-hint{bottom:55px}.quest-card{top:88px}}

(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const shell = document.getElementById('game-shell');
  const ui = {
    feed: document.getElementById('chatFeed'), input: document.getElementById('chatInput'),
    form: document.getElementById('chatForm'), coins: document.getElementById('coinCount'),
    progress: document.getElementById('questProgress'), quest: document.getElementById('questCount'),
    toast: document.getElementById('toast'), modal: document.getElementById('modalBackdrop')
  };
  const people = [
    {name:'Milo',color:'#f17466',hair:'#523d38',x:-180,z:45, line:'This plaza is so cozy 🌼'},
    {name:'Poppy',color:'#b887ed',hair:'#593957',x:200,z:-100,line:'Anyone found all the shiny coins?'},
    {name:'Kai',color:'#5faddb',hair:'#343e51',x:100,z:210,line:'The fountain is my favorite spot!'},
    {name:'Sunny',color:'#f0bd55',hair:'#9b5942',x:-245,z:-150,line:'Hi everyone! 👋'},
    {name:'Bean',color:'#72c89d',hair:'#443e4a',x:270,z:120,line:'Come say hello ✨'}
  ];
  const player = {x:0,z:100,vx:0,vz:0,y:0,vy:0,face:0,emote:'',emoteUntil:0,walk:0};
  const keys = new Set();
  const coins = [{x:-265,z:88},{x:245,z:-230},{x:340,z:54},{x:-342,z:-206},{x:36,z:337},{x:-80,z:-365},{x:410,z:350}].map((c,i)=>({...c,phase:i*1.7,taken:false}));
  const trees = [{x:-435,z:-355,s:1.15},{x:-435,z:345,s:1.3},{x:425,z:-365,s:1.2},{x:430,z:370,s:1.4},{x:-340,z:35,s:.92},{x:340,z:-45,s:.95},{x:60,z:-425,s:1.1},{x:55,z:435,s:1.05},{x:-205,z:420,s:.8},{x:210,z:-395,s:.8}];
  let width=0,height=0,dpr=1,last=performance.now(),elapsed=0,got=0,toastTimer=0,joystick={active:false,x:0,y:0,id:null};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const project=(x,z,y=0)=>({x:width/2+(x-z)*.72-camera.x,y:height*.49+(x+z)*.34-camera.y-y});
  const camera={x:0,y:0};
  function resize(){const r=shell.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  window.addEventListener('resize',resize);resize();
  function poly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke()}}
  function rounded(x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill()}
  function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill()}
  function line(x1,y1,x2,y2,color,w=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=w;ctx.lineCap='round';ctx.stroke()}
  function plane(cx,cz,rx,rz,color){const a=project(cx-rx,cz),b=project(cx,cz-rz),c=project(cx+rx,cz),d=project(cx,cz+rz);poly([a,b,c,d],color)}
  function say(name,text,kind=''){const el=document.createElement('div');el.className='chat-line'+(kind?' '+kind:'');if(kind==='system')el.textContent=text;else{const n=document.createElement('span');n.className='chat-name'+(name==='YOU'?' you':'');n.textContent=name;el.append(n,document.createTextNode(text))}ui.feed.append(el);while(ui.feed.children.length>24)ui.feed.firstChild.remove();ui.feed.scrollTop=ui.feed.scrollHeight}
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
  function drawGround(){
    const sky=ctx.createLinearGradient(0,0,0,height);sky.addColorStop(0,'#83bdc8');sky.addColorStop(.57,'#c4d6b3');sky.addColorStop(1,'#789b7b');ctx.fillStyle=sky;ctx.fillRect(0,0,width,height);
    // distant rolling hills and a tiny cloudscape
    ctx.fillStyle='#82b49d';ctx.beginPath();ctx.moveTo(0,height*.4);ctx.quadraticCurveTo(width*.16,height*.22,width*.35,height*.38);ctx.quadraticCurveTo(width*.55,height*.2,width*.76,height*.37);ctx.quadraticCurveTo(width*.88,height*.25,width,height*.36);ctx.lineTo(width,height*.58);ctx.lineTo(0,height*.58);ctx.fill();
    ctx.fillStyle='#bad5c0';for(let i=0;i<5;i++){let x=((i*281-elapsed*5)%(width+220)+width+220)%(width+220)-100,y=height*(.18+(i%3)*.07);ellipse(x,y,22,6,'#e2efe2aa');ellipse(x+15,y+1,13,5,'#e2efe2aa')}
    // broad grassy island with rounded-looking diamond corners
    const corners=[project(-560,-560),project(560,-560),project(560,560),project(-560,560)];poly(corners,'#86aa78','#71996f',4);
    // paved diamond plaza
    const p=[project(-365,-365),project(365,-365),project(365,365),project(-365,365)];poly(p,'#ded9c8','#f4e7c7',7);
    // subtle plaza tiles in diagonal rows
    ctx.save();ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);ctx.lineTo(p[1].x,p[1].y);ctx.lineTo(p[2].x,p[2].y);ctx.lineTo(p[3].x,p[3].y);ctx.closePath();ctx.clip();
    for(let i=-720;i<900;i+=58){let a=project(i,-390),b=project(i,390);line(a.x,a.y,b.x,b.y,'#c9c4b5aa',1);let c=project(-390,i),d=project(390,i);line(c.x,c.y,d.x,d.y,'#c9c4b5aa',1)}ctx.restore();
    // radial decorative inlays
    plane(0,0,190,190,'#e9dfc8');plane(0,0,172,172,'#d7c9a9');plane(0,0,160,160,'#e9dec6');
    for(let i=0;i<8;i++){const a=i*Math.PI/4;let c=project(Math.cos(a)*182,Math.sin(a)*182);ellipse(c.x,c.y,3,3,'#b7a982')}
  }
  function drawFountain(){const c=project(0,0);ellipse(c.x,c.y+20,78,27,'#b3a78f');ellipse(c.x,c.y+12,69,24,'#aaa28f');ellipse(c.x,c.y+1,61,21,'#8eaca9');ellipse(c.x,c.y-2,52,16,'#70b5bd');ellipse(c.x,c.y-3,42,11,'#83ced0');
    // ripples
    for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(c.x,c.y-3,15+i*11,4+i*3,0,0,Math.PI*2);ctx.strokeStyle='#c9f3e880';ctx.lineWidth=1.5;ctx.stroke()}
    const b=project(0,0,15);rounded(b.x-6,b.y-10,12,22,5,'#d6c39b');ellipse(b.x,b.y-10,8,5,'#fae2ad');ellipse(b.x,b.y-15-Math.sin(elapsed*3)*3,3,5,'#b8eff0')
  }
  function drawTree(t){const p=project(t.x,t.z),s=t.s;ellipse(p.x,p.y+4,25*s,9*s,'#344e3a40');rounded(p.x-5*s,p.y-27*s,10*s,33*s,4,'#896349');ellipse(p.x,p.y-34*s,27*s,29*s,'#3f805c');ellipse(p.x-12*s,p.y-45*s,18*s,20*s,'#55996c');ellipse(p.x+14*s,p.y-42*s,18*s,21*s,'#4b8c63');ellipse(p.x-2*s,p.y-55*s,15*s,18*s,'#68a878');ellipse(p.x-8*s,p.y-54*s,5*s,4*s,'#8fc88b')}
  function drawLamp(x,z){const p=project(x,z);ellipse(p.x,p.y+3,11,4,'#334c3c44');rounded(p.x-2,p.y-28,4,30,2,'#53666a');rounded(p.x-7,p.y-35,14,9,3,'#344d57');ellipse(p.x,p.y-37,7,5,'#ffe89b');ellipse(p.x,p.y-37,13,9,'#ffe89b33')}
  function drawBench(x,z,rot=0){const p=project(x,z);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(rot);ellipse(0,8,29,7,'#3d4d3e40');rounded(-26,-8,52,9,3,'#aa724b');rounded(-26,-17,52,8,3,'#c28a57');line(-19,-8,-21,5,'#5d5547',3);line(19,-8,21,5,'#5d5547',3);ctx.restore()}
  function drawKiosk(x,z){const p=project(x,z);ellipse(p.x,p.y+8,43,12,'#364c3e45');rounded(p.x-29,p.y-39,58,43,7,'#79b9ad');rounded(p.x-35,p.y-45,70,12,5,'#ee9867');poly([{x:p.x-35,y:p.y-42},{x:p.x,y:p.y-59},{x:p.x+35,y:p.y-42}], '#ffca76');rounded(p.x-23,p.y-28,46,26,3,'#eef1d9');rounded(p.x-20,p.y-24,40,8,2,'#e8a56c');ctx.fillStyle='#9ac5b9';ctx.font='700 7px sans-serif';ctx.textAlign='center';ctx.fillText('LEMONADE',p.x,p.y-12);rounded(p.x-7,p.y-10,14,15,2,'#906449')}
  function drawCoin(c){if(c.taken)return;const p=project(c.x,c.z,10+Math.sin(elapsed*3+c.phase)*5),pulse=1+Math.sin(elapsed*4+c.phase)*.08;ellipse(p.x,p.y+8,12,5,'#6e56364d');ctx.save();ctx.translate(p.x,p.y);ctx.scale(pulse,1);ellipse(0,0,8,10,'#cc8a35');ellipse(0,-2,7,9,'#ffd467');ellipse(0,-2,4,6,'#ffec9c');ctx.restore();ctx.fillStyle='#d89b3a';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('✦',p.x,p.y+1)}
  function drawCharacter(ch,isPlayer=false){const p=project(ch.x,ch.z,ch.y||0),moving=isPlayer&&Math.abs(player.vx)+Math.abs(player.vz)>.2,bob=moving?Math.abs(Math.sin(player.walk*9))*2:0;const face=isPlayer?player.face:Math.sin(elapsed*.65+(ch.x+ch.z)*.01)*.08;const col=isPlayer?'#56b7a9':ch.color;
    ellipse(p.x,p.y+4,14,6,'#354b3c55');
    if(isPlayer&&player.emote==='sit'&&player.emoteUntil>elapsed){rounded(p.x-10,p.y-19,20,20,6,col);ellipse(p.x,p.y-27,12,12,'#f1bd92');rounded(p.x-12,p.y-34,24,9,6,'#684a4b');return}
    // blocky legs, torso and head
    const step=moving?Math.sin(player.walk*9)*3:0;rounded(p.x-7,p.y-15+bob,6,14,2,'#425776');rounded(p.x+1,p.y-15+bob,6,14,2,'#354966');if(moving){line(p.x-4,p.y-5+bob,p.x-6-step,p.y+1,'#f0bd91',4);line(p.x+4,p.y-5+bob,p.x+6+step,p.y+1,'#f0bd91',4)}
    rounded(p.x-11,p.y-34+bob,22,21,5,col);rounded(p.x-15,p.y-32+bob,5,16,3,col);rounded(p.x+10,p.y-32+bob,5,16,3,col);
    const waving=isPlayer&&player.emote==='wave'&&player.emoteUntil>elapsed; if(waving){ctx.save();ctx.translate(p.x+12,p.y-28+bob);ctx.rotate(-.8+Math.sin(elapsed*12)*.15);rounded(-2,-14,5,18,3,col);ellipse(0,-16,4,4,'#f1bd92');ctx.restore()}
    ellipse(p.x,p.y-42+bob,12,12,'#f1bd92');ellipse(p.x,p.y-48+bob,13,7,isPlayer?'#40535a':ch.hair);rounded(p.x-12,p.y-48+bob,24,6,3,isPlayer?'#40535a':ch.hair);
    const fx=Math.sin(face)*3;ellipse(p.x-4+fx,p.y-42+bob,1.3,1.7,'#374653');ellipse(p.x+4+fx,p.y-42+bob,1.3,1.7,'#374653');
    if(isPlayer){ctx.fillStyle='#fff';ctx.font='800 10px sans-serif';ctx.textAlign='center';ctx.shadowColor='#182b32';ctx.shadowBlur=4;ctx.fillText('YOU',p.x,p.y-59+bob);ctx.shadowBlur=0}
    else{ctx.fillStyle='#fff';ctx.font='700 9px sans-serif';ctx.textAlign='center';ctx.shadowColor='#203c3c';ctx.shadowBlur=4;ctx.fillText(ch.name,p.x,p.y-59);ctx.shadowBlur=0}
  }
  function drawPetals(){for(let i=0;i<14;i++){const x=Math.sin(i*42.3)*400,z=Math.cos(i*21.2)*400,p=project(x,z);ellipse(p.x,p.y,2,1.2,i%2?'#fff5d8':'#f1b3a4')}}
  function render(){ctx.clearRect(0,0,width,height);drawGround();drawPetals();drawFountain();drawKiosk(-250,-260);drawKiosk(255,255);drawBench(-230,185,-.55);drawBench(240,-175,-.55);drawLamp(-105,-250);drawLamp(115,255);trees.forEach(drawTree);coins.forEach(drawCoin);
    const chars=[...people.map(ch=>({ch,depth:ch.x+ch.z})),{ch:player,depth:player.x+player.z,me:true}].sort((a,b)=>a.depth-b.depth);chars.forEach(({ch,me})=>drawCharacter(ch,me));
    // soft ambient sun flare
    const glow=ctx.createRadialGradient(width*.83,height*.15,2,width*.83,height*.15,130);glow.addColorStop(0,'#fff5cd38');glow.addColorStop(1,'#fff5cd00');ctx.fillStyle=glow;ctx.fillRect(width*.83-130,height*.15-130,260,260);
  }

  const filtered=(s)=>s.replace(/[^\p{L}\p{N}\p{P}\p{S} ]/gu,'').replace(/https?:\/\/\S+/gi,'[link]').trim();
  function update(dt){elapsed+=dt;const speed=205;let ix=0,iz=0;if(keys.has('KeyW')||keys.has('ArrowUp'))iz-=1;if(keys.has('KeyS')||keys.has('ArrowDown'))iz+=1;if(keys.has('KeyA')||keys.has('ArrowLeft'))ix-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))ix+=1;if(joystick.active){ix+=joystick.x;iz+=joystick.y}
    const mag=Math.hypot(ix,iz);if(mag>1){ix/=mag;iz/=mag}player.vx+=(ix*speed-player.vx)*Math.min(1,dt*10);player.vz+=(iz*speed-player.vz)*Math.min(1,dt*10);player.x=clamp(player.x+player.vx*dt,-475,475);player.z=clamp(player.z+player.vz*dt,-475,475);if(mag>.08){player.walk+=dt;player.face=Math.atan2(ix,iz)}else{player.vx*=Math.pow(.001,dt);player.vz*=Math.pow(.001,dt)}
    if(player.y>0||player.vy>0){player.y+=player.vy*dt;player.vy-=620*dt;if(player.y<=0){player.y=0;player.vy=0}}
    camera.x+=(player.x-player.z)*.72-camera.x;camera.y+=(player.x+player.z)*.34-camera.y;camera.x*=.045;camera.y*=.045;
    coins.forEach(c=>{if(c.taken)return;if(Math.hypot(player.x-c.x,player.z-c.z)<40){c.taken=true;got++;ui.coins.textContent=got;ui.quest.textContent=Math.min(got,5)+' / 5';ui.progress.style.width=Math.min(got,5)*20+'%';showToast(got>=5?'Quest complete! +100 bonus coins 🎉':'Shiny coin collected! +1 🪙');if(got===5){setTimeout(()=>{say('BLOCKTOWN','Daily quest complete! +100 bonus coins 🎉','system');},350)}}});
    if(Math.random()<dt*.22){const person=people[Math.floor(Math.random()*people.length)];if(!person.didChat){person.didChat=true;say(person.name,person.line);setTimeout(()=>{person.didChat=false},21000)}}
  }
  function frame(now){const dt=Math.min(.04,(now-last)/1000);last=now;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
  window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Space'){player.vy=player.y===0?270:player.vy}if(e.code==='Digit1')emote('wave');if(e.code==='Digit2')emote('dance');if(e.code==='Digit3')emote('sit');if(e.code==='Enter'&&document.activeElement!==ui.input){ui.input.focus()} });window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
  function emote(which){player.emote=which;player.emoteUntil=elapsed+(which==='sit'?2.4:which==='dance'?2.5:1.6);document.querySelectorAll('.hotkey[data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action===which));if(which==='dance')showToast('Dance party! 🕺');else if(which==='wave')showToast('You waved hello! 👋')}
  document.querySelectorAll('.hotkey[data-action]').forEach(b=>b.addEventListener('click',()=>emote(b.dataset.action)));
  ui.form.addEventListener('submit',e=>{e.preventDefault();const text=filtered(ui.input.value).slice(0,120);if(!text)return;say('YOU',text);ui.input.value='';ui.input.blur()});
  document.getElementById('chatToggle').addEventListener('click',()=>{const c=document.getElementById('chatPanel').classList.toggle('collapsed');document.getElementById('chatToggle').textContent=c?'+':'−'});
  document.getElementById('helpButton').addEventListener('click',()=>ui.modal.classList.add('open'));document.getElementById('modalClose').addEventListener('click',()=>ui.modal.classList.remove('open'));document.getElementById('playButton').addEventListener('click',()=>ui.modal.classList.remove('open'));ui.modal.addEventListener('click',e=>{if(e.target===ui.modal)ui.modal.classList.remove('open')});
  const editor=document.getElementById('nameEditor'),nameInput=document.getElementById('nameInput');document.getElementById('profileButton').addEventListener('click',()=>{editor.classList.toggle('open');nameInput.value=document.querySelector('.profile-name').textContent});document.getElementById('nameForm').addEventListener('submit',e=>{e.preventDefault();let name=filtered(nameInput.value).replace(/[<>]/g,'').slice(0,14).toUpperCase();if(name){document.querySelector('.profile-name').textContent=name;say('BLOCKTOWN',`You're now known as ${name}!`,'system')}editor.classList.remove('open')});
  function jump(){if(player.y===0)player.vy=270}document.getElementById('jumpButton').addEventListener('pointerdown',e=>{e.preventDefault();jump()});
  const stick=document.getElementById('joystick'),knob=document.getElementById('joyKnob');function joyStart(e){e.preventDefault();stick.setPointerCapture(e.pointerId);joystick.active=true;joystick.id=e.pointerId;joyMove(e)}function joyMove(e){if(!joystick.active||e.pointerId!==joystick.id)return;const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=31,dist=Math.hypot(dx,dy),scale=dist>lim?lim/dist:1;const x=dx*scale,y=dy*scale;knob.style.transform=`translate(${x}px,${y}px)`;joystick.x=x/lim;joystick.y=y/lim}function joyEnd(e){if(e.pointerId!==joystick.id)return;joystick.active=false;joystick.x=joystick.y=0;knob.style.transform=''}stick.addEventListener('pointerdown',joyStart);stick.addEventListener('pointermove',joyMove);stick.addEventListener('pointerup',joyEnd);stick.addEventListener('pointercancel',joyEnd);
  say('BLOCKTOWN','Welcome to Sunshine Plaza! Collect coins and say hi ✨','system');say('Poppy','Aww, the fountain looks so pretty today 🌼');say('Milo','Hi! Use WASD to walk around 👋');
  setTimeout(()=>{if(!sessionStorage.getItem('blocktownWelcome')){ui.modal.classList.add('open');sessionStorage.setItem('blocktownWelcome','1')}},450);
})();

