(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const shell = document.getElementById('game-shell');
  const ui = { feed: document.getElementById('chatFeed'), input: document.getElementById('chatInput'), form: document.getElementById('chatForm'), coins: document.getElementById('coinCount'), progress: document.getElementById('questProgress'), quest: document.getElementById('questCount'), toast: document.getElementById('toast'), modal: document.getElementById('modalBackdrop') };
  const people = [
    {name:'Milo',color:'#f17466',hair:'#523d38',x:-180,z:45,line:'This plaza is so cozy 🌼'},
    {name:'Poppy',color:'#b887ed',hair:'#593957',x:200,z:-100,line:'Anyone found all the shiny coins?'},
    {name:'Kai',color:'#5faddb',hair:'#343e51',x:100,z:210,line:'The fountain is my favorite spot!'},
    {name:'Sunny',color:'#f0bd55',hair:'#9b5942',x:-245,z:-150,line:'Hi everyone! 👋'},
    {name:'Bean',color:'#72c89d',hair:'#443e4a',x:270,z:120,line:'Come say hello ✨'}
  ];
  const player = {x:0,z:100,vx:0,vz:0,y:0,vy:0,face:0,emote:'',emoteUntil:0,walk:0};
  const keys = new Set();
  const coins = [{x:-265,z:88},{x:245,z:-230},{x:340,z:54},{x:-342,z:-206},{x:36,z:337},{x:-80,z:-365},{x:410,z:350}].map((c,i)=>({...c,phase:i*1.7,taken:false}));
  const trees = [{x:-435,z:-355,s:1.15},{x:-435,z:345,s:1.3},{x:425,z:-365,s:1.2},{x:430,z:370,s:1.4},{x:-340,z:35,s:.92},{x:340,z:-45,s:.95},{x:60,z:-425,s:1.1},{x:55,z:435,s:1.05},{x:-205,z:420,s:.8},{x:210,z:-395,s:.8}];
  let width=0,height=0,dpr=1,last=performance.now(),elapsed=0,got=0,toastTimer=0,joystick={active:false,x:0,y:0,id:null};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const project=(x,z,y=0)=>({x:width/2+(x-z)*.72-camera.x,y:height*.49+(x+z)*.34-camera.y-y});
  const camera={x:0,y:0};
  function resize(){const r=shell.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  window.addEventListener('resize',resize);resize();
  function poly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke()}}
  function rounded(x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill()}
  function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill()}
  function line(x1,y1,x2,y2,color,w=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=w;ctx.lineCap='round';ctx.stroke()}
  function plane(cx,cz,rx,rz,color){const a=project(cx-rx,cz),b=project(cx,cz-rz),c=project(cx+rx,cz),d=project(cx,cz+rz);poly([a,b,c,d],color)}
  function say(name,text,kind=''){const el=document.createElement('div');el.className='chat-line'+(kind?' '+kind:'');if(kind==='system')el.textContent=text;else{const n=document.createElement('span');n.className='chat-name'+(name==='YOU'?' you':'');n.textContent=name;el.append(n,document.createTextNode(text))}ui.feed.append(el);while(ui.feed.children.length>24)ui.feed.firstChild.remove();ui.feed.scrollTop=ui.feed.scrollHeight}
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
  function drawGround(){
