  window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Space'&&document.activeElement!==ui.input)player.vy=player.y===0?270:player.vy;if(e.code==='Digit1')emote('wave');if(e.code==='Digit2')emote('dance');if(e.code==='Digit3')emote('sit');if(e.code==='Enter'&&document.activeElement!==ui.input)ui.input.focus()});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
