  function jump(){if(player.y===0)player.vy=270}document.getElementById('jumpButton').addEventListener('pointerdown',e=>{e.preventDefault();jump()});
  const stick=document.getElementById('joystick'),knob=document.getElementById('joyKnob');function joyStart(e){e.preventDefault();stick.setPointerCapture(e.pointerId);joystick.active=true;joystick.id=e.pointerId;joyMove(e)}function joyMove(e){if(!joystick.active||e.pointerId!==joystick.id)return;const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=31,dist=Math.hypot(dx,dy),scale=dist>lim?lim/dist:1,x=dx*scale,y=dy*scale;knob.style.transform=`translate(${x}px,${y}px)`;joystick.x=x/lim;joystick.y=y/lim}function joyEnd(e){if(e.pointerId!==joystick.id)return;joystick.active=false;joystick.x=joystick.y=0;knob.style.transform=''}stick.addEventListener('pointerdown',joyStart);stick.addEventListener('pointermove',joyMove);stick.addEventListener('pointerup',joyEnd);stick.addEventListener('pointercancel',joyEnd);
  say('BLOCKTOWN','Welcome to Sunshine Plaza! Collect coins and say hi ✨','system');say('Poppy','Aww, the fountain looks so pretty today 🌼');say('Milo','Hi! Use WASD to walk around 👋');
  setTimeout(()=>{if(!sessionStorage.getItem('blocktownWelcome')){ui.modal.classList.add('open');sessionStorage.setItem('blocktownWelcome','1')}},450);
})();

