(()=>{
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),shell=document.querySelector('#game-shell');
const $=s=>document.querySelector(s), ui={feed:$('#chatFeed'),input:$('#chatInput'),coins:$('#coinCount'),progress:$('#questProgress'),quest:$('#questCount'),toast:$('#toast'),modal:$('#modalBackdrop')};
const player={x:0,z:100,vx:0,vz:0,y:0,vy:0,walk:0,face:0,emote:'',until:0},keys=new Set();
const people=[{name:'Milo',color:'#f17466',hair:'#523d38',x:-180,z:45,line:'This plaza is so cozy 🌼'},{name:'Poppy',color:'#b887ed',hair:'#593957',x:200,z:-100,line:'Anyone found all the shiny coins?'},{name:'Kai',color:'#5faddb',hair:'#343e51',x:100,z:210,line:'The fountain is my favorite spot!'},{name:'Sunny',color:'#f0bd55',hair:'#9b5942',x:-245,z:-150,line:'Hi everyone! 👋'},{name:'Bean',color:'#72c89d',hair:'#443e4a',x:270,z:120,line:'Come say hello ✨'}];
const coins=[[-265,88],[245,-230],[340,54],[-342,-206],[36,337],[-80,-365],[410,350]].map(([x,z],i)=>({x,z,phase:i*1.7,taken:false}));
const trees=[[-435,-355,1.15],[-435,345,1.3],[425,-365,1.2],[430,370,1.4],[-340,35,.92],[340,-45,.95],[60,-425,1.1],[55,435,1.05],[-205,420,.8],[210,-395,.8]];
let w=0,h=0,dpr=1,last=performance.now(),time=0,count=0,toastTimer,stick={active:false,x:0,y:0,id:null},cam={x:0,y:0};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),p=(x,z,y=0)=>({x:w/2+(x-z)*.72-cam.x,y:h*.49+(x+z)*.34-cam.y-y});
function resize(){const r=shell.getBoundingClientRect();w=r.width;h=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function poly(a,color,stroke){ctx.beginPath();a.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=4;ctx.stroke()}}
function rect(x,y,a,b,r,c){ctx.beginPath();ctx.roundRect(x,y,a,b,r);ctx.fillStyle=c;ctx.fill()}
function oval(x,y,a,b,c){ctx.beginPath();ctx.ellipse(x,y,a,b,0,0,Math.PI*2);ctx.fillStyle=c;ctx.fill()}
function stroke(x,y,a,b,c='#ddd',lw=1){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(a,b);ctx.strokeStyle=c;ctx.lineWidth=lw;ctx.lineCap='round';ctx.stroke()}
function diamond(x,z,rx,rz,color){poly([p(x-rx,z),p(x,z-rz),p(x+rx,z),p(x,z+rz)],color)}
function say(name,text,system=false){const el=document.createElement('div');el.className='chat-line'+(system?' system':'');if(system)el.textContent=text;else{const n=document.createElement('span');n.className='chat-name'+(name==='YOU'?' you':'');n.textContent=name;el.append(n,document.createTextNode(text))}ui.feed.append(el);while(ui.feed.children.length>24)ui.feed.firstChild.remove();ui.feed.scrollTop=ui.feed.scrollHeight}
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function ground(){let g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#83bdc8');g.addColorStop(.57,'#c4d6b3');g.addColorStop(1,'#789b7b');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.fillStyle='#82b49d';ctx.beginPath();ctx.moveTo(0,h*.4);ctx.quadraticCurveTo(w*.16,h*.22,w*.35,h*.38);ctx.quadraticCurveTo(w*.55,h*.2,w*.76,h*.37);ctx.quadraticCurveTo(w*.88,h*.25,w,h*.36);ctx.lineTo(w,h*.58);ctx.lineTo(0,h*.58);ctx.fill();
 poly([p(-560,-560),p(560,-560),p(560,560),p(-560,560)],'#86aa78','#71996f');let a=[p(-365,-365),p(365,-365),p(365,365),p(-365,365)];poly(a,'#ded9c8','#f4e7c7');ctx.save();ctx.beginPath();a.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.clip();for(let i=-720;i<900;i+=58){let q=p(i,-390),r=p(i,390);stroke(q.x,q.y,r.x,r.y,'#c9c4b5aa');q=p(-390,i);r=p(390,i);stroke(q.x,q.y,r.x,r.y,'#c9c4b5aa')}ctx.restore();diamond(0,0,190,190,'#e9dfc8');diamond(0,0,172,172,'#d7c9a9');diamond(0,0,160,160,'#e9dec6');
 for(let i=0;i<5;i++){let x=((i*281-time*5)%(w+220)+w+220)%(w+220)-100,y=h*(.18+(i%3)*.07);oval(x,y,22,6,'#e2efe2aa');oval(x+15,y+1,13,5,'#e2efe2aa')}}
function fountain(){let c=p(0,0);oval(c.x,c.y+20,78,27,'#b3a78f');oval(c.x,c.y+12,69,24,'#aaa28f');oval(c.x,c.y+1,61,21,'#8eaca9');oval(c.x,c.y-2,52,16,'#70b5bd');oval(c.x,c.y-3,42,11,'#83ced0');for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(c.x,c.y-3,15+i*11,4+i*3,0,0,Math.PI*2);ctx.strokeStyle='#c9f3e880';ctx.stroke()}let b=p(0,0,15);rect(b.x-6,b.y-10,12,22,5,'#d6c39b');oval(b.x,b.y-10,8,5,'#fae2ad');oval(b.x,b.y-15-Math.sin(time*3)*3,3,5,'#b8eff0')}
function tree(t){let [x,z,s]=t,c=p(x,z);oval(c.x,c.y+4,25*s,9*s,'#344e3a40');rect(c.x-5*s,c.y-27*s,10*s,33*s,4,'#896349');oval(c.x,c.y-34*s,27*s,29*s,'#3f805c');oval(c.x-12*s,c.y-45*s,18*s,20*s,'#55996c');oval(c.x+14*s,c.y-42*s,18*s,21*s,'#4b8c63');oval(c.x-2*s,c.y-55*s,15*s,18*s,'#68a878')}
function kiosk(x,z){let c=p(x,z);oval(c.x,c.y+8,43,12,'#364c3e45');rect(c.x-29,c.y-39,58,43,7,'#79b9ad');rect(c.x-35,c.y-45,70,12,5,'#ee9867');poly([{x:c.x-35,y:c.y-42},{x:c.x,y:c.y-59},{x:c.x+35,y:c.y-42}],'#ffca76');rect(c.x-23,c.y-28,46,26,3,'#eef1d9');rect(c.x-20,c.y-24,40,8,2,'#e8a56c');ctx.fillStyle='#4b837b';ctx.font='700 7px sans-serif';ctx.textAlign='center';ctx.fillText('LEMONADE',c.x,c.y-12);rect(c.x-7,c.y-10,14,15,2,'#906449')}
function bench(x,z,r){let c=p(x,z);ctx.save();ctx.translate(c.x,c.y);ctx.rotate(r);oval(0,8,29,7,'#3d4d3e40');rect(-26,-8,52,9,3,'#aa724b');rect(-26,-17,52,8,3,'#c28a57');stroke(-19,-8,-21,5,'#5d5547',3);stroke(19,-8,21,5,'#5d5547',3);ctx.restore()}
function coin(c){if(c.taken)return;let q=p(c.x,c.z,10+Math.sin(time*3+c.phase)*5);oval(q.x,q.y+8,12,5,'#6e56364d');oval(q.x,q.y,8,10,'#cc8a35');oval(q.x,q.y-2,7,9,'#ffd467');oval(q.x,q.y-2,4,6,'#ffec9c');ctx.fillStyle='#d89b3a';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('✦',q.x,q.y+1)}

function character(c,me=false){let q=p(c.x,c.z,c.y||0),moving=me&&Math.abs(player.vx)+Math.abs(player.vz)>.2,bob=moving?Math.abs(Math.sin(player.walk*9))*2:0,col=me?'#56b7a9':c.color;oval(q.x,q.y+4,14,6,'#354b3c55');if(me&&player.emote==='sit'&&player.until>time){rect(q.x-10,q.y-19,20,20,6,col);oval(q.x,q.y-27,12,12,'#f1bd92');return}rect(q.x-7,q.y-15+bob,6,14,2,'#425776');rect(q.x+1,q.y-15+bob,6,14,2,'#354966');rect(q.x-11,q.y-34+bob,22,21,5,col);rect(q.x-15,q.y-32+bob,5,16,3,col);rect(q.x+10,q.y-32+bob,5,16,3,col);let wave=me&&player.emote==='wave'&&player.until>time;if(wave){ctx.save();ctx.translate(q.x+12,q.y-28+bob);ctx.rotate(-.8+Math.sin(time*12)*.15);rect(-2,-14,5,18,3,col);oval(0,-16,4,4,'#f1bd92');ctx.restore()}oval(q.x,q.y-42+bob,12,12,'#f1bd92');oval(q.x,q.y-48+bob,13,7,me?'#40535a':c.hair);rect(q.x-12,q.y-48+bob,24,6,3,me?'#40535a':c.hair);oval(q.x-4,q.y-42+bob,1.3,1.7,'#374653');oval(q.x+4,q.y-42+bob,1.3,1.7,'#374653');ctx.fillStyle='#fff';ctx.font=me?'800 10px sans-serif':'700 9px sans-serif';ctx.textAlign='center';ctx.shadowColor='#203c3c';ctx.shadowBlur=4;ctx.fillText(me?'YOU':c.name,q.x,q.y-59+bob);ctx.shadowBlur=0}
function render(){ctx.clearRect(0,0,w,h);ground();fountain();kiosk(-250,-260);kiosk(255,255);bench(-230,185,-.55);bench(240,-175,-.55);trees.forEach(tree);coins.forEach(coin);[...people.map(c=>({c,d:c.x+c.z})),{c:player,d:player.x+player.z,me:true}].sort((a,b)=>a.d-b.d).forEach(o=>character(o.c,o.me));let glow=ctx.createRadialGradient(w*.83,h*.15,2,w*.83,h*.15,130);glow.addColorStop(0,'#fff5cd38');glow.addColorStop(1,'#fff5cd00');ctx.fillStyle=glow;ctx.fillRect(w*.83-130,h*.15-130,260,260)}
function emote(which){player.emote=which;player.until=time+(which==='sit'?2.4:which==='dance'?2.5:1.6);document.querySelectorAll('.hotkey[data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action===which));if(which==='dance')toast('Dance party! 🕺');else if(which==='wave')toast('You waved hello! 👋')}
function update(dt){time+=dt;let x=0,z=0;if(keys.has('KeyW')||keys.has('ArrowUp'))z--;if(keys.has('KeyS')||keys.has('ArrowDown'))z++;if(keys.has('KeyA')||keys.has('ArrowLeft'))x--;if(keys.has('KeyD')||keys.has('ArrowRight'))x++;if(stick.active){x+=stick.x;z+=stick.y}let m=Math.hypot(x,z);if(m>1){x/=m;z/=m}let speed=205;player.vx+=(x*speed-player.vx)*Math.min(1,dt*10);player.vz+=(z*speed-player.vz)*Math.min(1,dt*10);player.x=clamp(player.x+player.vx*dt,-475,475);player.z=clamp(player.z+player.vz*dt,-475,475);if(m>.08)player.walk+=dt;else{player.vx*=Math.pow(.001,dt);player.vz*=Math.pow(.001,dt)}if(player.y>0||player.vy>0){player.y+=player.vy*dt;player.vy-=620*dt;if(player.y<=0)player.y=player.vy=0}cam.x+=((player.x-player.z)*.72-cam.x)*Math.min(1,dt*4);cam.y+=((player.x+player.z)*.34-cam.y)*Math.min(1,dt*4);
 coins.forEach(c=>{if(!c.taken&&Math.hypot(player.x-c.x,player.z-c.z)<40){c.taken=true;count++;ui.coins.textContent=count;ui.quest.textContent=Math.min(count,5)+' / 5';ui.progress.style.width=Math.min(count,5)*20+'%';toast(count>=5?'Quest complete! +100 bonus coins 🎉':'Shiny coin collected! +1 🪙');if(count===5)setTimeout(()=>say('BLOCKTOWN','Daily quest complete! +100 bonus coins 🎉',true),350)}});if(Math.random()<dt*.22){let c=people[Math.floor(Math.random()*people.length)];if(!c.didChat){c.didChat=true;say(c.name,c.line);setTimeout(()=>c.didChat=false,21000)}}}
function frame(now){let dt=Math.min(.04,(now-last)/1000);last=now;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);

function jump(){if(player.y===0)player.vy=270}function safeText(s){return s.replace(/https?:\/\/\S+/gi,'[link]').trim()}
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Space'&&document.activeElement!==ui.input)jump();if(e.code==='Digit1')emote('wave');if(e.code==='Digit2')emote('dance');if(e.code==='Digit3')emote('sit');if(e.code==='Enter'&&document.activeElement!==ui.input)ui.input.focus()});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>keys.clear());
document.querySelectorAll('.hotkey[data-action]').forEach(b=>b.addEventListener('click',()=>emote(b.dataset.action)));
$('#chatForm').addEventListener('submit',e=>{e.preventDefault();let text=safeText(ui.input.value).slice(0,120);if(text){say('YOU',text);ui.input.value='';ui.input.blur()}});
$('#chatToggle').addEventListener('click',()=>{let c=$('#chatPanel').classList.toggle('collapsed');$('#chatToggle').textContent=c?'+':'−'});
$('#helpButton').addEventListener('click',()=>ui.modal.classList.add('open'));$('#modalClose').addEventListener('click',()=>ui.modal.classList.remove('open'));$('#playButton').addEventListener('click',()=>ui.modal.classList.remove('open'));ui.modal.addEventListener('click',e=>{if(e.target===ui.modal)ui.modal.classList.remove('open')});
const editor=$('#nameEditor'),nameInput=$('#nameInput');$('#profileButton').addEventListener('click',()=>{editor.classList.toggle('open');nameInput.value=$('.profile-name').textContent});$('#nameForm').addEventListener('submit',e=>{e.preventDefault();let n=safeText(nameInput.value).replace(/[<>]/g,'').slice(0,14).toUpperCase();if(n){$('.profile-name').textContent=n;say('BLOCKTOWN',`You're now known as ${n}!`,true)}editor.classList.remove('open')});
$('#jumpButton').addEventListener('pointerdown',e=>{e.preventDefault();jump()});
const stickEl=$('#joystick'),knob=$('#joyKnob');function joyStart(e){e.preventDefault();stickEl.setPointerCapture(e.pointerId);stick.active=true;stick.id=e.pointerId;joyMove(e)}function joyMove(e){if(!stick.active||e.pointerId!==stick.id)return;let r=stickEl.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,lim=31,dist=Math.hypot(dx,dy),s=dist>lim?lim/dist:1,x=dx*s,y=dy*s;knob.style.transform=`translate(${x}px,${y}px)`;stick.x=x/lim;stick.y=y/lim}function joyEnd(e){if(e.pointerId!==stick.id)return;stick.active=false;stick.x=stick.y=0;knob.style.transform=''}stickEl.addEventListener('pointerdown',joyStart);stickEl.addEventListener('pointermove',joyMove);stickEl.addEventListener('pointerup',joyEnd);stickEl.addEventListener('pointercancel',joyEnd);
say('BLOCKTOWN','Welcome to Sunshine Plaza! Collect coins and say hi ✨',true);say('Poppy','Aww, the fountain looks so pretty today 🌼');say('Milo','Hi! Use WASD to walk around 👋');setTimeout(()=>{if(!sessionStorage.getItem('blocktownWelcome')){ui.modal.classList.add('open');sessionStorage.setItem('blocktownWelcome','1')}},450);
})();

